    fbBuilder.addOffset(0, offset);
    return fbBuilder.offset;
  }
  int addUpstreamRepositoryOffset(int? offset) {
    fbBuilder.addOffset(1, offset);
    return fbBuilder.offset;
  }
  int addUpstreamRevisionOffset(int? offset) {
    fbBuilder.addOffset(2, offset);
    return fbBuilder.offset;
  }
  int addRegistryPathOffset(int? offset) {
    fbBuilder.addOffset(3, offset);
    return fbBuilder.offset;
  }
  int addGeneratedAtMs(int? GENERATED_AT_MS) {
    fbBuilder.addInt64(4, GENERATED_AT_MS);
    return fbBuilder.offset;
  }
  int addProvidersOffset(int? offset) {
    fbBuilder.addOffset(5, offset);
    return fbBuilder.offset;
  }
  int addResourcesOffset(int? offset) {
    fbBuilder.addOffset(6, offset);
    return fbBuilder.offset;
  }
  int addReceiptsOffset(int? offset) {
    fbBuilder.addOffset(7, offset);
    return fbBuilder.offset;
  }
  int addStatusOffset(int? offset) {
    fbBuilder.addOffset(8, offset);
    return fbBuilder.offset;
  }
  int addSettingsOffset(int? offset) {
    fbBuilder.addOffset(9, offset);
    return fbBuilder.offset;
  }

  int finish() {
    return fbBuilder.endTable();
  }
}

class SRGObjectBuilder extends fb.ObjectBuilder {
  final String? _REGISTRY_ID;
  final String? _UPSTREAM_REPOSITORY;
  final String? _UPSTREAM_REVISION;
  final String? _REGISTRY_PATH;
  final int? _GENERATED_AT_MS;
  final List<SRGProviderObjectBuilder>? _PROVIDERS;
  final List<SRGResourceObjectBuilder>? _RESOURCES;
  final List<SRGContentReceiptObjectBuilder>? _RECEIPTS;
  final SRGRetrievalStatusObjectBuilder? _STATUS;
  final SRGRetrievalSettingsObjectBuilder? _SETTINGS;

  SRGObjectBuilder({
    String? REGISTRY_ID,
    String? registryId,
    String? UPSTREAM_REPOSITORY,
    String? upstreamRepository,
    String? UPSTREAM_REVISION,
    String? upstreamRevision,
    String? REGISTRY_PATH,
    String? registryPath,
    int? GENERATED_AT_MS,
    int? generatedAtMs,
    List<SRGProviderObjectBuilder>? PROVIDERS,
    List<SRGResourceObjectBuilder>? RESOURCES,
    List<SRGContentReceiptObjectBuilder>? RECEIPTS,
    SRGRetrievalStatusObjectBuilder? STATUS,
    SRGRetrievalSettingsObjectBuilder? SETTINGS,
  })
      : _REGISTRY_ID = registryId ?? REGISTRY_ID,
        _UPSTREAM_REPOSITORY = upstreamRepository ?? UPSTREAM_REPOSITORY,
        _UPSTREAM_REVISION = upstreamRevision ?? UPSTREAM_REVISION,
        _REGISTRY_PATH = registryPath ?? REGISTRY_PATH,
        _GENERATED_AT_MS = generatedAtMs ?? GENERATED_AT_MS,
        _PROVIDERS = PROVIDERS,
        _RESOURCES = RESOURCES,
        _RECEIPTS = RECEIPTS,
        _STATUS = STATUS,
        _SETTINGS = SETTINGS;

  /// Finish building, and store into the [fbBuilder].
  @override
  int finish(fb.Builder fbBuilder) {
    final int? REGISTRY_IDOffset = _REGISTRY_ID == null ? null
        : fbBuilder.writeString(_REGISTRY_ID!);
    final int? UPSTREAM_REPOSITORYOffset = _UPSTREAM_REPOSITORY == null ? null
        : fbBuilder.writeString(_UPSTREAM_REPOSITORY!);
    final int? UPSTREAM_REVISIONOffset = _UPSTREAM_REVISION == null ? null
        : fbBuilder.writeString(_UPSTREAM_REVISION!);
    final int? REGISTRY_PATHOffset = _REGISTRY_PATH == null ? null
        : fbBuilder.writeString(_REGISTRY_PATH!);
    final int? PROVIDERSOffset = _PROVIDERS == null ? null
        : fbBuilder.writeList(_PROVIDERS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? RESOURCESOffset = _RESOURCES == null ? null
        : fbBuilder.writeList(_RESOURCES!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? RECEIPTSOffset = _RECEIPTS == null ? null
        : fbBuilder.writeList(_RECEIPTS!.map((b) => b.getOrCreateOffset(fbBuilder)).toList());
    final int? STATUSOffset = _STATUS?.getOrCreateOffset(fbBuilder);
    final int? SETTINGSOffset = _SETTINGS?.getOrCreateOffset(fbBuilder);
    fbBuilder.startTable(10);
    fbBuilder.addOffset(0, REGISTRY_IDOffset);
    fbBuilder.addOffset(1, UPSTREAM_REPOSITORYOffset);
    fbBuilder.addOffset(2, UPSTREAM_REVISIONOffset);
    fbBuilder.addOffset(3, REGISTRY_PATHOffset);
    fbBuilder.addInt64(4, _GENERATED_AT_MS);
    fbBuilder.addOffset(5, PROVIDERSOffset);
    fbBuilder.addOffset(6, RESOURCESOffset);
    fbBuilder.addOffset(7, RECEIPTSOffset);
    fbBuilder.addOffset(8, STATUSOffset);
    fbBuilder.addOffset(9, SETTINGSOffset);
    return fbBuilder.endTable();
  }

  /// Convenience method to serialize to byte list.
  @override
  Uint8List toBytes([String? fileIdentifier]) {
    final fbBuilder = fb.Builder(deduplicateTables: false);
    fbBuilder.finish(finish(fbBuilder), fileIdentifier);
    return fbBuilder.buffer;
  }
}
